/**
 * Explicit app-local opt-in for a single-stage request owned by the surviving
 * AppContext. Separate from the existing contract interface for binary safety:
 * prebuilt, non-opted-in contracts do not need a new Kotlin default method.
 */
interface AppContextActivityResultRetention<I : Serializable> {
  fun shouldRetainCallbackOnHostDestroy(input: I): Boolean
}

