private fun releaseRetainedCallback(key: String) {
  retainedCallbackKeys.remove(key)
  launchedKeys.remove(key)
  keyToCallbacksAndContract.remove(key)
  keyToInputParam.remove(key)
  pendingResults.remove(key)
  keyToRequestCode.remove(key)?.let { requestCodeToKey.remove(it) }
  keyToLifecycleContainers.remove(key)?.clearObservers()
}

/** AppContext destruction is final, unlike host Activity destruction. */
fun disposeRetainedCallbacks() {
  keyToCallbacksAndContract.filterValues { it.retainCallbackOnHostDestroy }
    .keys.toList().forEach { releaseRetainedCallback(it) }
}

