fun onDestroy() {
  // AppContext destruction can arrive off-main. Do not enqueue on its
  // cancelled coroutine scope or mutate registry maps on that caller thread.
  if (Looper.myLooper() == Looper.getMainLooper()) {
    registry.disposeRetainedCallbacks()
  } else {
    Handler(Looper.getMainLooper()).post { registry.disposeRetainedCallbacks() }
  }
}

) : AppContextActivityResultContract<CameraContractOptions, ImagePickerContractResult>, AppContextActivityResultRetention<CameraContractOptions> {
  // The app uses single-stage, non-editing picks. Editing may launch a crop
  // Activity before replacement launchers register, so it is not opted in.
  override fun shouldRetainCallbackOnHostDestroy(input: CameraContractOptions): Boolean =
    !input.options.allowsEditing

override fun parseResult(input: CameraContractOptions, resultCode: Int, intent: Intent?): ImagePickerContractResult {
  if (input.options.allowsEditing) return parsePickerResult(input, resultCode, intent)
  // Unreadable/revoked provider URIs must reject the original native promise,
  // not throw before its retained continuation can settle and release ownership.
  return try {
    parsePickerResult(input, resultCode, intent)
  } catch (cause: Exception) {
    ImagePickerContractResult.Error
  }
}

